// Diagram -> Terraform: turns the canvas's nodes/edges into a sample .tf file.
//
// Every node whose catalog entry has a real Terraform resource type gets a
// resource block. Its body is a sample taken from one of ArchLens's reference
// architectures (window.TF_SAMPLES, generated by scripts/gen_tf_samples.py) —
// blocks that already pass ArchLens's own analysis. References inside a sample
// are rewired: to the matching node on the diagram if there is one, otherwise
// to a declared variable, so the file stays valid Terraform. A type with no
// sample gets a TODO body; a service with no Terraform resource at all is
// listed as a TODO comment instead of a fabricated resource type.
// Copyright (c) 2026 K.N.Narin (github.com/narin-kura). All rights reserved.
// Non-commercial use only. See LICENSE.

// Current major versions (Terraform Registry, 2026-11-03). Samples are
// validated with `terraform validate` against these.
const TF_PROVIDER_META = {
  'aws_':         {key: 'aws',         source: 'hashicorp/aws',         version: '~> 6.0'},
  'azurerm_':     {key: 'azurerm',     source: 'hashicorp/azurerm',     version: '~> 5.0'},
  'azuread_':     {key: 'azuread',     source: 'hashicorp/azuread',     version: '~> 3.0'},
  'azuredevops_': {key: 'azuredevops', source: 'microsoft/azuredevops', version: '~> 1.0'},
  'google_':      {key: 'google',      source: 'hashicorp/google',      version: '~> 8.0'},
  'oci_':         {key: 'oci',         source: 'oracle/oci',            version: '~> 9.0'},
  'vsphere_':     {key: 'vsphere',     source: 'vmware/vsphere',        version: '~> 2.0'},
  'openstack_':   {key: 'openstack',   source: 'terraform-provider-openstack/openstack', version: '~> 3.0'},
  'nutanix_':     {key: 'nutanix',     source: 'nutanix/nutanix',       version: '~> 2.0'},
  'proxmox_':     {key: 'proxmox',     source: 'bpg/proxmox',           version: '~> 0.120'},
};

// Docker products like Docker Hub or Scout also use a docker_ id but have no
// Terraform resource, so Docker is matched by exact type, not by prefix.
const TF_DOCKER_TYPES = new Set([
  'docker_container', 'docker_image', 'docker_tag', 'docker_registry_image', 'docker_service',
  'docker_secret', 'docker_config', 'docker_plugin', 'docker_buildx_builder', 'docker_compose',
  'docker_network', 'docker_volume',
]);
const TF_DOCKER_PROVIDER = {key: 'docker', source: 'kreuzwerker/docker', version: '~> 4.0'};

// A reference to another resource inside a sample body:
// [data.]<type>.<name><rest>, e.g. aws_subnet.private[*].id
const TF_REF = /\b(data\.)?((?:aws|azurerm|azuread|azuredevops|google|oci|random|docker|vsphere|openstack|nutanix|proxmox)_[a-z0-9_]+)\.([A-Za-z0-9_-]+)((?:\[[^\]]*\])?(?:\.[A-Za-z0-9_]+(?:\[[^\]]*\])?)*)/g;

function tfProviderFor(type) {
  if (!type) return null;
  // Types the current provider doesn't have (retired, or a catalog slug that
  // only looks like a resource type) — listed as TODOs, never as blocks.
  const unsupported = (typeof window !== 'undefined' && window.TF_UNSUPPORTED_TYPES) || [];
  if (unsupported.includes(type)) return null;
  if (TF_DOCKER_TYPES.has(type)) return TF_DOCKER_PROVIDER;
  for (const prefix of Object.keys(TF_PROVIDER_META)) {
    if (type.startsWith(prefix)) return TF_PROVIDER_META[prefix];
  }
  return null;
}

// AWS catalog entries keep a short slug in `service` (what the analyzers key
// on) and carry the real resource type in `tf`.
function tfTypeFor(node) {
  const svc = (typeof findService === 'function' && node.svcId) ? findService(node.svcId) : null;
  return (svc && svc.tf) || node.tf || node.service;
}

function tfSlug(name, fallback) {
  let s = (name || fallback || 'resource').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  if (!s) s = 'resource';
  if (/^[0-9]/.test(s)) s = 'r_' + s;
  return s;
}

function tfUniqueLabel(type, base, used) {
  let label = base, n = 1;
  while (used.has(type + '::' + label)) { n++; label = base + '_' + n; }
  used.add(type + '::' + label);
  return label;
}

function tfRewireSample(body, ownAddress, addressByType) {
  return body
    .replace(TF_REF, (match, data, type, name, rest) => {
      const target = !data && addressByType.get(type);
      const leadingIndex = (rest.match(/^\[[^\]]*\]/) || [''])[0];
      const attrs = rest.slice(leadingIndex.length);
      if (target && target !== ownAddress) {
        // The diagram node is a single resource, so drop count/for_each indexing;
        // a splat ([*]) was producing a list, so keep it a list.
        return leadingIndex === '[*]' ? `[${target}${attrs}]` : `${target}${attrs}`;
      }
      const attr = (attrs.match(/^\.([A-Za-z0-9_]+)/) || [null, 'id'])[1];
      const base = type.replace(/^[a-z]+_/, '') + '_' + attr + (leadingIndex === '[*]' ? 's' : '');
      return `var.${base}`;
    })
    .replace(/\blocal\.([A-Za-z0-9_]+)/g, 'var.$1')
    // file("app.crt") would make `terraform validate` fail until the file
    // exists; the contents become an input instead.
    .replace(/\b(?:file|filebase64)\("([^"]+)"\)/g,
             (m, path) => 'var.' + tfSlug(path.split('/').pop(), 'file') + '_content');
}

function buildTerraformExport(diagramNodes, diagramEdges) {
  const samples = (typeof window !== 'undefined' && window.TF_SAMPLES) || {};
  const used = new Set();
  const addrByUid = new Map();     // uid -> "type.label", real resources only
  const typeByUid = new Map();
  const addressByType = new Map(); // first diagram node of each type
  const providersUsed = new Map();
  const unmapped = [];

  // Tiers run left-to-right the same way autoArrange lays the canvas out, so
  // the generated file reads top-to-bottom roughly how the diagram reads
  // left-to-right.
  const tierIndex = n => {
    const i = (typeof TIER_ORDER !== 'undefined') ? TIER_ORDER.indexOf(n.type) : -1;
    return i === -1 ? 999 : i;
  };
  const ordered = [...diagramNodes].sort((a, b) => tierIndex(a) - tierIndex(b));

  ordered.forEach(n => {
    const type = tfTypeFor(n);
    const provider = tfProviderFor(type);
    if (!provider) { unmapped.push(n); return; }
    providersUsed.set(provider.key, provider);
    const address = `${type}.${tfUniqueLabel(type, tfSlug(n.name, type), used)}`;
    addrByUid.set(n.uid, address);
    typeByUid.set(n.uid, type);
    if (!addressByType.has(type)) addressByType.set(type, address);
  });

  const dependsByUid = new Map();
  diagramEdges.forEach(e => {
    if (!dependsByUid.has(e.to)) dependsByUid.set(e.to, []);
    dependsByUid.get(e.to).push(e.from);
  });

  const variables = new Set();
  let sampled = 0;
  const resourceBlocks = ordered
    .filter(n => addrByUid.has(n.uid))
    .map(n => {
      const address = addrByUid.get(n.uid);
      const type = typeByUid.get(n.uid);
      const label = address.slice(type.length + 1);
      const sample = samples[type];
      const lines = [`resource "${type}" "${label}" {`];
      let body = '';
      if (sample) {
        sampled++;
        body = tfRewireSample(sample.body, address, addressByType);
        (body.match(/\bvar\.[A-Za-z0-9_]+/g) || []).forEach(v => variables.add(v.slice(4)));
        lines.push(`  # Sample from ${sample.from}`);
        lines.push(`  # (drawn as "${n.name}"). Names, sizes and CIDRs are examples — review them.`);
        lines.push(body);
      } else {
        lines.push(`  # TODO: no sample for ${type} yet — drawn as "${n.name}" on the diagram.`);
      }
      // Only arrows the sample doesn't already express as a reference.
      const deps = (dependsByUid.get(n.uid) || [])
        .map(fromUid => addrByUid.get(fromUid))
        .filter(dep => dep && !body.includes(dep));
      if (deps.length) {
        if (sample) lines.push('');
        lines.push(`  depends_on = [${deps.join(', ')}]`);
      }
      lines.push('}');
      return lines.join('\n');
    });

  const out = [];
  out.push('# Generated by ArchLens from a diagram on ' + new Date().toISOString().slice(0, 10) + '.');
  out.push('#');
  out.push('# Sample Terraform, not a finished deployment:');
  out.push('#   - Each resource body is copied from one of ArchLens\'s reference');
  out.push('#     architectures: secure defaults, but example names, sizes and CIDRs.');
  out.push('#   - References to resources on your diagram are wired to them; anything');
  out.push('#     else a sample needs is a variable declared below — set it, or');
  out.push('#     replace it with your own resource.');
  out.push('#   - depends_on covers diagram arrows the samples don\'t already express.');
  out.push('#   - Components with no Terraform resource type are listed as TODOs at the');
  out.push('#     end instead of a guessed resource type.');

  if (providersUsed.size) {
    out.push('');
    out.push('terraform {');
    out.push('  required_providers {');
    [...providersUsed.values()].forEach(p => {
      out.push(`    ${p.key} = {`);
      out.push(p.version ? `      source  = "${p.source}"` : `      source = "${p.source}"`);
      if (p.version) out.push(`      version = "${p.version}"`);
      out.push('    }');
    });
    out.push('  }');
    out.push('}');
  }

  if (variables.size) {
    out.push('');
    out.push('# ---- Inputs the samples need that aren\'t on your diagram ----');
    [...variables].sort().forEach(v => {
      out.push('');
      out.push(`variable "${v}" {`);
      out.push(`  description = "Set to the ${v.replace(/_/g, ' ')} in your environment."`);
      out.push('}');
    });
  }

  if (resourceBlocks.length) {
    out.push('');
    out.push(resourceBlocks.join('\n\n'));
  }

  if (unmapped.length) {
    out.push('');
    out.push('# ---- No Terraform resource type ----');
    out.push('# These have no resource in their Terraform provider (or none ArchLens has');
    out.push('# confirmed), so no block was generated. Add them by hand:');
    unmapped.forEach(n => out.push(`#   - "${n.name}" (${n.provider})`));
  }

  if (diagramEdges.length) {
    out.push('');
    out.push('# ---- Diagram connections ----');
    diagramEdges.forEach(e => {
      const a = diagramNodes.find(n => n.uid === e.from);
      const b = diagramNodes.find(n => n.uid === e.to);
      if (!a || !b) return;
      const left = addrByUid.get(a.uid) || `"${a.name}"`;
      const right = addrByUid.get(b.uid) || `"${b.name}"`;
      out.push(`#   ${left} -> ${right}${e.label ? `   ["${e.label}"]` : ''}`);
    });
  }

  out.push('');
  return {hcl: out.join('\n'), sampled};
}

function exportDiagramAsTerraform() {
  if (!nodes.length) return;
  const {hcl} = buildTerraformExport(nodes, edges);
  const blob = new Blob([hcl], {type: 'text/plain'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = 'archlens-diagram.tf';
  a.click();
  URL.revokeObjectURL(url);
}
